struct Subject {
  std::vector<std::pair<int, std::function<void(const Event&)>>> subs_;
  int next_id_ = 0;
  int subscribe(std::function<void(const Event&)> f) {
    subs_.emplace_back(next_id_, std::move(f)); return next_id_++;
  }
  void unsubscribe(int id) {
    subs_.erase(std::remove_if(subs_.begin(), subs_.end(),
               [id](const auto& p) { return p.first == id; }), subs_.end());
  }
  void notify(const Event& e) const { for (const auto& p : subs_) p.second(e); }
};

